t.script:
// Enfocar automáticamente el input al cargar la página
document.addEventListener('DOMContentLoaded', function() {
    var input = document.getElementById('barcode-input');
    if (input) {
        input.focus();
    }
});

// Función para obtener y mostrar la hora actual
function displayCurrentTime() {
    var now = new Date();
    var hours = now.getHours().toString().padStart(2, '0');
    var minutes = now.getMinutes().toString().padStart(2, '0');
    var seconds = now.getSeconds().toString().padStart(2, '0');
    var currentTime = hours + ':' + minutes + ':' + seconds;
    var span = document.getElementById('current-time');
    if (span) {
        span.textContent = 'Hora actual: ' + currentTime;
    }
}

// Mostrar hora inicial
displayCurrentTime();
// Actualizar cada segundo
setInterval(displayCurrentTime, 1000);

// Enviar formulario al presionar Enter en el input de barcode
document.addEventListener('DOMContentLoaded', function() {
    var input = document.getElementById('barcode-input');
    if (input) {
        input.addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                var form = document.getElementById('scan-form');
                if (form) {
                    form.submit();
                }
            }
        });
    }
});

body.style:
background-image: url('/lunch_time/static/img/fondo.png');
                     background-size: cover;
                     background-position: center;
                     background-repeat: no-repeat;

